def evaluate(current_reputation, observation, my_history, round_num):
    # Asymmetric scoring: defections hurt more than cooperations help
    if observation['action'] == 'cooperate':
        base = 0.5
    else:
        base = -1.0
    # Recency weight: recent rounds matter more (round_num increases)
    weight = round_num / 10.0  # max 0.5 at round 5
    # Adjust based on current reputation: trustworthy agents are judged more harshly on defection
    if observation['action'] == 'defect' and current_reputation > 0.3:
        base -= 0.3  # extra penalty
    elif observation['action'] == 'cooperate' and current_reputation < -0.3:
        base += 0.3  # extra reward for cooperating with low-rep agent
    updated = base * weight
    # Clamp to [-1.0, 1.0]
    return max(-1.0, min(1.0, updated))

def decide(recipient_reputation, round_num, my_history):
    # First two rounds: always cooperate to build trust
    if round_num <= 2:
        return True
    # After that, cooperate only if reputation is not too negative
    if recipient_reputation >= -0.2:
        return True
    # If we have cooperated more than half the time in the past, be generous
    own_coop = sum(1 for entry in my_history if entry['action'] == 'cooperate')
    if own_coop >= (round_num - 1) * 0.5:
        return True
    return False
